// coverage:ignore-file
import 'dart:io';

import 'package:cse_cet_reviewer/core/content/content_database.dart';
import 'package:drift/native.dart';
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';

const contentDbFileName = 'content.db';

/// Bumped whenever `assets/seed/content.db` is regenerated by
/// `tools/build_content_seed/seed_writer.dart`. It is how a device knows the
/// copy it installed is older than the one in the app it just updated to.
/// Content 01, 01b and 03 each regenerated the asset and none of them bumped
/// this, so a device that had already installed the July copy would have
/// skipped all three: no passages, no lesson links, no blueprint. The JSON
/// seeder that used to backfill the gap is gone, so there is nothing behind it.
const contentSeedVersion = '2026-08-11';

Future<ContentDatabase> openContentDatabase() async {
  final dir = await getApplicationSupportDirectory();
  final file = File(p.join(dir.path, contentDbFileName));
  return ContentDatabase(NativeDatabase.createInBackground(file));
}
